import{timelineEvents,dynasties}from"../data.js";export function DynastyTimeline(){const e=document.createElement("div");e.className="dynasty-timeline-container";const n=[...timelineEvents].sort((e,n)=>e.year-n.year),t=n[0].year,s=n[n.length-1].year-t,a=document.createElement("div");return a.className="dynasty-timeline",n.forEach((e,n)=>{const i=(e.year-t)/s*100,l=dynasties.find(n=>n.id===e.dynasty),r=n%2==0,c=document.createElement("div");c.className="timeline-event "+(r?"left":"right"),c.style.setProperty("--pos",`${i}%`);const o=e.year<0?`${Math.abs(e.year)} BCE`:`${e.year} CE`;c.innerHTML=`\n      <div class="timeline-dot" style="background:${l?l.color:"#666"}"></div>\n      <div class="timeline-content">\n        <span class="timeline-year" style="color:${l?l.color:"#666"}">${o}</span>\n        <p class="timeline-text">${e.event}</p>\n        <span class="timeline-dynasty">${l?l.name:""}</span>\n      </div>\n    `,a.appendChild(c)}),e.innerHTML='<h3 class="section-subtitle">Chronological Timeline</h3>',e.appendChild(a),e}